local function print(...)
	local a = {...}
	for i, v in ipairs(a) do
		a[i] = tostring(v)
	end
	OutputMessage("MSG_SYS", "[xMacro]" .. table.concat(a, "\t") .. "\n" )
end


local function Compare(szCmp, szRes, szTar)
	local nRes, nTar = tonumber(szRes), tonumber(szTar)
	if not nRes or not nTar then return false end
	if szCmp == "=" or szCmp == "==" then
		return nRes == nTar
	elseif szCmp == ">" then
		return nRes > nTar
	elseif szCmp == "<" then
		return nRes < nTar
	elseif szCmp == ">=" then
		return nRes >= nTar
	elseif szCmp == "<=" then
		return nRes <= nTar
	end
	return false
end


