setmetatable(tOptions, {__index = function(t, k)
	local function callback(...)
		if k == "true" then
			return true
		elseif k == "false" then
			return false
		else
			if string.sub(k, 1, 1) == "!" then
				if string.sub(k, 2, 2) == "t" then
					k = "tno" .. string.sub(k, 3, -1)
				else
					k = "no" .. string.sub(k, 2, -1)
				end
				return t[k](...)
			else
				print("Tham số [" .. k .. "] sai!")
				return false
			end
		end
	end
	return callback
end})


local function UITestCast(dwSkillID, dwLevel, index)
	local me = (MeCache and MeCache.Get and MeCache:Get()) or GetClientPlayer()
	if not me then return false end

	-- 0. Pet skills (index == 2): luon o che do SPAM vi khong ton GCD cua nhan vat
	if index == 2 then
		return true
	end

	local nCurFrame = (GetLogicFrameCount and GetLogicFrameCount()) or 0
	local okOT, nOT = pcall(function() return me.GetOTActionState() end)
	local nOTState = okOT and tonumber(nOT or 0) or 0
	local nStand = (MOVE_STATE and MOVE_STATE.ON_STAND) or 0
	local bStanding = (me.nMoveState or nStand) == nStand

	-- Ngung Than Tu Khi (300): khong tin GCD nen co the cast ngay trong GCD khi qidian < 8 va dang dung yen
	if dwSkillID == 300 then
		if nOTState ~= 0 then
			return false
		end
		if me.GetSkillPrepareState then
			local okP, bPrep = pcall(function() return me.GetSkillPrepareState() end)
			if okP and bPrep then
				return false
			end
		end
		if not bStanding then
			return false
		end
		if nNgungThanCooldownUntilFrame > 0 and nCurFrame < nNgungThanCooldownUntilFrame then
			return false
		end
		if tSkillCastFrame and tSkillCastFrame[300] then
			local diff = nCurFrame - tSkillCastFrame[300]
			if diff >= 0 and diff < 2 then
				return false
			end
		end
		return true
	end

	-- Kiem tra buff Vu Tap (cho phep danh Tu Tuong Luan Hoi 367 tuc thoi khi di chuyen)
	local bVuTap = false
	if not bStanding and (dwSkillID == 367 or dwSkillID == 306) then
		local aBuff = MyGetBuffList and MyGetBuffList(me)
		if aBuff and (IsBuffExist(aBuff, "Vũ Tập") or IsBuffExist(aBuff, "Vu Tap") or IsBuffExist(aBuff, "雨集")) then
			bVuTap = true
		end
	end

	-- Cac chieu van cong / dan dao cua Thuan Duong yeu cau dung yen (khi di chuyen se roi xuong Thai Cuc Vo Cuc 306)
	if not bStanding then
		if dwSkillID == 367 and not bVuTap then
			return false
		elseif dwSkillID == 359 or dwSkillID == 357 or dwSkillID == 358 or dwSkillID == 362 or dwSkillID == 368 then
			return false
		end
	end

	-- Thai Cuc Vo Cuc (306): CHI danh khi TAT CA cac skill khac khong the danh (tuc la dang di chuyen, qidian < 8, khong co Vu Tap)
	if dwSkillID == 306 then
		if bStanding then
			return false
		end
		if (me.nAccumulateValue or 0) >= 8 then
			return false
		end
		if bVuTap then
			return false
		end
		if nNgungThanCooldownUntilFrame > 0 and nCurFrame < nNgungThanCooldownUntilFrame then
			return false
		end
	end

	-- 1. Kiem tra trang thai thi trien:
	if not IsOTStuck(me) then
		if nOTState == 1 then
			return false
		elseif nOTState == 2 then
			-- Dang dan dao (channel):
			-- Neu dang dan dao Ngung Than Tu Khi (300) hoac khong bat bao ve channel:
			-- Cho phep kiem tra CD/GCD thuc te cua skill (nhu Luong Nghi Hoa Hinh 301, Tu Tuong Luan Hoi 367) o buoc 3 & 4
			local bIsNgungThan = IsChannelingNgungThan(me) or (dwCurrentChannelSkillID == 300) or (me.dwForceID == 5 and dwCurrentChannelSkillID ~= 368)
			if not bIsNgungThan and bProtectChannelSkill then
				return false
			end
		else
			if me.GetSkillPrepareState then
				local okP, bPrep, dwPrepID = pcall(function() return me.GetSkillPrepareState() end)
				if okP and bPrep and tonumber(dwPrepID or 0) ~= 300 then
					return false
				end
			end
		end
	end
	if not tOffGCDSkill[dwSkillID] and GetTime and nGlobalCastLockUntil > 0 and GetTime() < nGlobalCastLockUntil then
		return false
	end

	-- 1b. Bao ve tuyet doi: Khong cho phep Hat Tam (2209) de nhip Bach Tuc (2212)
	if dwSkillID == 2209 then
		local now = (GetTime and GetTime()) or 0
		if nGlobalCastLockUntil > 0 and now < nGlobalCastLockUntil then
			return false
		end
		if me.GetSkillCDProgress then
			local okCD, bCool, nLeft = pcall(function() return me.GetSkillCDProgress(2212, 1) end)
			if okCD and (not bCool or tonumber(nLeft or 0) <= 0) then
				return false
			end
		end
	end

	-- 2. Anti-double-cast debounce: chong spam frame lien tiep khi goi tin server chua kip tra ve
	if tSkillCastFrame and tSkillCastFrame[dwSkillID] then
		local nCur = (GetLogicFrameCount and GetLogicFrameCount()) or 0
		local nDebounce = ((dwSkillID == 189 or dwSkillID == 190) and 36) or (dwSkillID == 2212 and 8) or 4
		local diff = nCur - tSkillCastFrame[dwSkillID]
		if diff >= 0 and diff < nDebounce then
			return false
		end
	end

	-- 2b. Kiem tra trang thai Active ("sang") cho cac chieu dac thu khong co Cooldown (CD = 0)
	-- hoac chi co the thi trien khi dat dieu kien dac biet (tranh stall toan bo macro khi chua sang):
	-- A. Minh Giao: Tinh The Pha Ma Kich (3967) va Sinh Tu Kiep (3969)
	-- Chi sang va su dung duoc khi Man Nhat (nSunPowerValue == 1) hoac Man Nguyet (nMoonPowerValue == 1).
	if dwSkillID == 3967 or dwSkillID == 3969 then
		local bSun = (me.nSunPowerValue == 1 or me.nSunPowerValue == true)
			or (me.nCurrentSunEnergy and me.nCurrentSunEnergy >= 100)
		local bMoon = (me.nMoonPowerValue == 1 or me.nMoonPowerValue == true)
			or (me.nCurrentMoonEnergy and me.nCurrentMoonEnergy >= 100)
		if not bSun and not bMoon then
			return false
		end
	end

	-- B. Minh Giao: Khu Da Doan Sau (3979)
	-- Chi sang va su dung duoc khi dang o trang thai An Than (Stealth) hoac co buff Am Tran Di Son (4052).
	if dwSkillID == 3979 then
		local bActive = false
		if me.bStealth or me.bInStealth then
			bActive = true
		end
		if not bActive then
			local aBuff = MyGetBuffList and MyGetBuffList(me)
			if aBuff then
				if IsBuffExist(aBuff, 4052) or IsBuffExist(aBuff, "Ám Trần Di Sơn") or IsBuffExist(aBuff, "暗尘弥散") then
					bActive = true
				end
			end
		end
		if not bActive then
			return false
		end
	end

	-- Fallback: Engine CanUseSkill (neu client co ho tro ham nay)
	if me.CanUseSkill then
		local okU, bCan = pcall(function() return me.CanUseSkill(dwSkillID, dwLevel or 1) end)
		if okU and bCan == false then
			-- Neu dang van khi Ngung Than Tu Khi (300), client C++ co the tra ve false vi dang OTState channeling.
			-- Cho phep vuot qua kiem tra nay de OnCastPlayerSkill ngat Ngung Than thi trien skill moi (nhu Luong Nghi Hoa Hinh).
			local bIsChanNT = (nOTState == 2 and IsChannelingNgungThan(me) and dwSkillID ~= 300)
			if not bIsChanNT then
				return false
			end
		end
	end

	-- 3. Kiem tra Cooldown qua Engine Player truc tiep (chinh xac 100%, khong phu thuoc UI)
	if me.GetSkillCDProgress then
		local bCool, nLeft = me.GetSkillCDProgress(dwSkillID, dwLevel or 1)
		if bCool and tonumber(nLeft or 0) > 0 then
			return false
		end
	end
	-- 4. Kiem tra qua UI Box neu co (chi kiem tra IsObjectCoolDown, khong dung IsObjectEnable de tranh bi chan goc mat/cu ly tren dummy box)
	local box = tSkillBox[index]
	if box and box.SetObject then
		box:SetObject(UI_OBJECT_SKILL, dwSkillID, dwLevel or 1)
		if UpdataSkillCDProgress then
			UpdataSkillCDProgress(me, box)
		end
		if box.IsObjectCoolDown and box:IsObjectCoolDown() then
			return false
		end
	end
	return true
end


