local function GetSmartTargetXYZ(skillID)
	local me = (MeCache and MeCache.Get and MeCache:Get()) or (GetClientPlayer and GetClientPlayer())
	if not me then return nil, nil, nil end

	local nSkillID = tonumber(skillID) or _lastGroundSkillID

	-- Neu la Khi Truong Thuan Duong:
	-- "cac khi truong se tu tha duoi chan, tru Sinh thai cuc va toai tinh than la tha vao muc tieu"
	if nSkillID and tThuanDuongQiFields and tThuanDuongQiFields[nSkillID] then
		if not (tTargetQiFields and tTargetQiFields[nSkillID]) then
			-- Cac khi truong con lai (Pha Thuong Khung, Hoa Tam Thanh, Thon Nhat Nguyet, Tran Son Ha...):
			-- Tu dong tha duoi chan nhan vat (Self)!
			if me.nX and me.nY and me.nZ then
				return me.nX, me.nY, me.nZ
			end
		end
	end

	-- Sinh Thai Cuc (358), Toai Tinh Than (362) hoac ky nang dat vung cua phai khac:
	-- Uu tien tha vao muc tieu (Target)
	local tar = (GetCurrentTargetObject and GetCurrentTargetObject()) or (TarCache and TarCache.Get and TarCache:Get())
	if not tar and me.GetTarget then
		local ok, dwType, dwID = pcall(function() return me.GetTarget() end)
		if ok and dwID and dwID > 0 then
			tar = (GetTargetHandle and GetTargetHandle(dwType, dwID)) or (GetNpc and GetNpc(dwID)) or (GetPlayer and GetPlayer(dwID))
		end
	end
	if tar and tar.nCurrentLife and tar.nCurrentLife <= 0 then
		tar = nil
	end
	if tar and tar.nX and tar.nY and tar.nZ then
		return tar.nX, tar.nY, tar.nZ
	end
	if me.nX and me.nY and me.nZ then
		return me.nX, me.nY, me.nZ
	end
	return nil, nil, nil
end
_G.GetSmartTargetXYZ = GetSmartTargetXYZ

local function GetMouseTargetXYZ()
	local me = (MeCache and MeCache.Get and MeCache:Get()) or (GetClientPlayer and GetClientPlayer())
	local cx, cy = nil, nil
	if Cursor and Cursor.GetPos then
		local ok, x, y = pcall(Cursor.GetPos)
		if ok and x and y then cx, cy = x, y end
	end
	if not cx or not cy then
		if GetCursorPos then
			local ok, x, y = pcall(GetCursorPos)
			if ok and x and y then cx, cy = x, y end
		end
	end
	if cx and cy then
		if AIO and type(AIO.GetScreenPoint) == "function" then
			local ok, wx, wy, wz = pcall(AIO.GetScreenPoint, cx, cy)
			if ok and wx and wy and wz then
				return wx, wy, wz
			end
		end
		if Scene and type(Scene.ScreenToWorld) == "function" then
			local ok, wx, wy, wz = pcall(Scene.ScreenToWorld, cx, cy)
			if ok and wx and wy and wz then
				return wx, wy, wz
			end
		end
	end
	local tx, ty, tz = GetSmartTargetXYZ()
	if tx and ty and tz then
		return tx, ty, tz
	end
	if me and me.nX and me.nY and me.nZ then
		return me.nX, me.nY, me.nZ
	end
	return nil, nil, nil
end
_G.GetMouseTargetXYZ = GetMouseTargetXYZ

local function SyncAIOTLHelperBachTuc()
	local mode = (xMacro and xMacro.GroundTargetMode) or "target"
	if AIO_TLHelper then
		local tlMode = 3
		if mode == "mouse" then
			tlMode = 2
		elseif mode == "manual" then
			tlMode = 0
		end
		if type(AIO_TLHelper.tTrapList) == "table" then
			AIO_TLHelper.tTrapList[2212] = tlMode
			AIO_TLHelper.tTrapList[2492] = tlMode
			AIO_TLHelper.tTrapList[2496] = tlMode
			AIO_TLHelper.tTrapList[5764] = tlMode
			for qid, _ in pairs(tThuanDuongQiFields or {}) do
				if tTargetQiFields and tTargetQiFields[qid] then
					AIO_TLHelper.tTrapList[qid] = (mode == "mouse") and 2 or (mode == "manual" and 0 or 3)
				else
					AIO_TLHelper.tTrapList[qid] = (mode == "manual") and 0 or 1
				end
			end
		end
		if type(AIO_TLHelper.tTrapMode) == "table" then
			AIO_TLHelper.tTrapMode[2212] = tlMode
			AIO_TLHelper.tTrapMode[2492] = tlMode
			AIO_TLHelper.tTrapMode[2496] = tlMode
			AIO_TLHelper.tTrapMode[5764] = tlMode
		end
		if tlMode > 0 then
			AIO_TLHelper.bAutoTrap = true
		end
	end
	if HM_Force and type(HM_Force.tSelfQC) == "table" then
		for qid, _ in pairs(tThuanDuongQiFields or {}) do
			if tTargetQiFields and tTargetQiFields[qid] then
				HM_Force.tSelfQC[qid] = false -- Sinh Thai Cuc & Toai Tinh Than tha vao Target
			else
				HM_Force.tSelfQC[qid] = true  -- Cac khi truong con lai (Pha Thuong Khung, Hoa Tam Thanh...) tha duoi chan
			end
		end
	end
end
_G.SyncAIOTLHelperBachTuc = SyncAIOTLHelperBachTuc

local function PrepareGroundSkillOnTarget(dwSkillID)
	local nID = tonumber(dwSkillID)
	if not nID or (not tCombatGroundSkills[nID] and not tGroundTargetSkill[nID] and nID ~= 2212) then
		return
	end
	local mode = (xMacro and xMacro.GroundTargetMode) or "target"
	SyncAIOTLHelperBachTuc()
	if mode == "manual" then
		_lastGroundSkillID = nil
		_lastGroundSkillTime = 0
		return
	end
	local now = (GetTime and GetTime()) or 0
	_lastGroundSkillID = nID
	_lastGroundSkillTime = now
	if AIO_TLHelper and type(AIO_TLHelper.ForcePlace) == "function" then
		local tlMode = (mode == "mouse") and 2 or 3
		if tThuanDuongQiFields and tThuanDuongQiFields[nID] and not (tTargetQiFields and tTargetQiFields[nID]) then
			tlMode = 1 -- Mode 1 trong AIO_TLHelper la duoi chan (Self)
		end
		pcall(AIO_TLHelper.ForcePlace, nID, tlMode)
	end
end
_G.PrepareGroundSkillOnTarget = PrepareGroundSkillOnTarget

local function DoSmartSelectPoint(dwSkillID)
	local mode = (xMacro and xMacro.GroundTargetMode) or "target"
	if mode == "manual" then return false end
	local x, y, z
	if mode == "mouse" then
		x, y, z = GetMouseTargetXYZ(dwSkillID)
	else
		x, y, z = GetSmartTargetXYZ(dwSkillID)
	end
	if x and y and z and UserSelect and UserSelect.DoSelectPoint then
		pcall(UserSelect.DoSelectPoint, x, y, z)
		return true
	end
	return false
end
_G.DoSmartSelectPoint = DoSmartSelectPoint

local function GetCurrentGroundSkillID(...)
	for i = 1, select("#", ...) do
		local v = select(i, ...)
		if type(v) == "number" and (tCombatGroundSkills[v] or tGroundTargetSkill[v] or v == 2212) then
			return v
		elseif type(v) == "table" or type(v) == "userdata" then
			if v.GetObjectData then
				local ok, id = pcall(v.GetObjectData, v)
				if ok and type(id) == "number" and (tCombatGroundSkills[id] or tGroundTargetSkill[id] or id == 2212) then
					return id
				end
			end
			for _, k in ipairs({"dwSkillID", "dwID", "nSkillID", "dwSkill", "nID"}) do
				local id = tonumber(v[k])
				if id and (tCombatGroundSkills[id] or tGroundTargetSkill[id] or id == 2212) then
					return id
				end
			end
		end
	end
	if this and (type(this) == "table" or type(this) == "userdata") then
		if this.GetObjectData then
			local ok, id = pcall(this.GetObjectData, this)
			if ok and type(id) == "number" and (tCombatGroundSkills[id] or tGroundTargetSkill[id] or id == 2212) then
				return id
			end
		end
		for _, k in ipairs({"dwSkillID", "dwID", "nSkillID", "dwSkill", "nID"}) do
			local id = tonumber(this[k])
			if id and (tCombatGroundSkills[id] or tGroundTargetSkill[id] or id == 2212) then
				return id
			end
		end
	end
	local now = (GetTime and GetTime()) or 0
	if _lastGroundSkillID and (now >= _lastGroundSkillTime) and (now - _lastGroundSkillTime <= 2000) then
		return _lastGroundSkillID
	end
	return nil
end

local function MakeSelectPointInterceptor(origFn)
	return function(fnCallback, ...)
		local mode = (xMacro and xMacro.GroundTargetMode) or "target"
		local skillID = GetCurrentGroundSkillID(...)
		-- TUYET DOI KHONG can thiep vao vat pham lam nhiem vu hoac thao tac chon vung ngoai ky nang!
		if not skillID or mode == "manual" then
			_lastGroundSkillID = nil
			_lastGroundSkillTime = 0
			if origFn then
				return origFn(fnCallback, ...)
			end
			return
		end

		-- Day la ky nang chien dau dat vung (Bach Tuc 2212, Khi Truong, v.v.)
		local x, y, z
		if mode == "mouse" then
			x, y, z = GetMouseTargetXYZ(skillID)
		else
			x, y, z = GetSmartTargetXYZ(skillID)
		end

		_lastGroundSkillID = nil
		_lastGroundSkillTime = 0

		if x and y and z then
			-- 1. Uu tien goi callback truc tiep neu engine truyen vao
			if type(fnCallback) == "function" then
				local ok = pcall(fnCallback, x, y, z)
				if ok then
					_lastGroundSkillID = nil
					_lastGroundSkillTime = 0
					return
				end
			end
			-- 2. Snap ngay lap tuc bang DoSelectPoint truc tiep
			-- TUYET DOI KHONG goi origFn(fnCallback, ...) o day vi cac addon khac (nhu HM_Force)
			-- co hook UserSelect.SelectPoint se lap tuc chen DoSelectPoint(tar.nX, tar.nY, tar.nZ) vao Target!
			if UserSelect and UserSelect.DoSelectPoint then
				pcall(UserSelect.DoSelectPoint, x, y, z)
			end
			_lastGroundSkillID = nil
			_lastGroundSkillTime = 0
			return
		end

		_lastGroundSkillID = nil
		_lastGroundSkillTime = 0

		if origFn then
			return origFn(fnCallback, ...)
		end
	end
end

local function MakeDoSelectPointInterceptor(origFn)
	return function(x, y, z, ...)
		local mode = (xMacro and xMacro.GroundTargetMode) or "target"
		if mode ~= "manual" then
			local skillID = GetCurrentGroundSkillID()
			if skillID and tThuanDuongQiFields and tThuanDuongQiFields[skillID] then
				if not (tTargetQiFields and tTargetQiFields[skillID]) then
					-- Day la khi truong dat duoi chan (Pha Thuong Khung, Hoa Tam Thanh, Thon Nhat Nguyet, Tran Son Ha...)
					local me = (MeCache and MeCache.Get and MeCache:Get()) or (GetClientPlayer and GetClientPlayer())
					if me and me.nX and me.nY and me.nZ then
						x, y, z = me.nX, me.nY, me.nZ
					end
				end
			end
		end
		if origFn then
			return origFn(x, y, z, ...)
		end
	end
end

local function MakeSkillUseInterceptor(origFn)
	return function(dwSkillID, dwLevel, ...)
		local nID = tonumber(dwSkillID)
		if nID and (nID == 2212 or tCombatGroundSkills[nID] or tGroundTargetSkill[nID]) then
			PrepareGroundSkillOnTarget(nID)
		end
		if origFn then
			return origFn(dwSkillID, dwLevel, ...)
		end
	end
end

local function HookUserSelectPoint()
	SyncAIOTLHelperBachTuc()
	local tSlots = {
		{ tbl = UserSelect, name = "SelectPoint", key = "UserSelect.SelectPoint", maker = MakeSelectPointInterceptor },
		{ tbl = UserSelect, name = "SelectArea", key = "UserSelect.SelectArea", maker = MakeSelectPointInterceptor },
		{ tbl = UserSelect, name = "DoSelectPoint", key = "UserSelect.DoSelectPoint", maker = MakeDoSelectPointInterceptor },
		{ tbl = _G, name = "SelectPoint", key = "_G.SelectPoint", maker = MakeSelectPointInterceptor },
		{ tbl = _G, name = "UserSelectPoint", key = "_G.UserSelectPoint", maker = MakeSelectPointInterceptor },
		{ tbl = _G, name = "DoSelectPoint", key = "_G.DoSelectPoint", maker = MakeDoSelectPointInterceptor },
		{ tbl = _G, name = "OnUseSkill", key = "_G.OnUseSkill", maker = MakeSkillUseInterceptor },
		{ tbl = _G, name = "OnCastPlayerSkill", key = "_G.OnCastPlayerSkill", maker = MakeSkillUseInterceptor },
		{ tbl = _G, name = "OnAddOnUseSkill", key = "_G.OnAddOnUseSkill", maker = MakeSkillUseInterceptor },
	}
	for _, s in ipairs(tSlots) do
		local tbl = s.tbl
		if type(tbl) == "table" and type(tbl[s.name]) == "function" then
			local curFn = tbl[s.name]
			if not _tXMacroWrapped[s.key] or curFn == _tXMacroOrig[s.key] then
				_tXMacroOrig[s.key] = curFn
				local wrapped = s.maker(curFn)
				_tXMacroWrapped[s.key] = wrapped
				pcall(function() tbl[s.name] = wrapped end)
			end
		end
	end
end
HookUserSelectPoint()

local function OnCastPlayerSkill(me, dwSkillID, dwLevel)
	local nCur = (GetLogicFrameCount and GetLogicFrameCount()) or 0
	local okOT, nOT = pcall(function() return me.GetOTActionState() end)
	local bIsChanneling = okOT and tonumber(nOT or 0) == 2
	local bWasChanneling = false

	-- Dan dao: neu dang kep Ngung Than Tu Khi (300) hoac khong bat bao ve thi ngat dan dao de danh skill moi
	local bIsNgungThan = IsChannelingNgungThan(me) or (dwCurrentChannelSkillID == 300) or (me.dwForceID == 5 and dwCurrentChannelSkillID ~= 368)
	if bIsChanneling and dwSkillID ~= 300 then
		if bIsNgungThan or not bProtectChannelSkill then
			if me.StopCurrentAction then
				pcall(function() me.StopCurrentAction() end)
			end
			dwCurrentChannelSkillID = 0
			szLastOTA = nil
			nNgungThanCooldownUntilFrame = nCur + 6
			bWasChanneling = true
			bIsChanneling = false
		else
			-- Dang dan dao chieu tan cong / ho tro (nhu Luc Hop Doc Ton 368, Tuy Vu 2235...) va co bao ve dan dao
			return false
		end
	end

	if not (bIsChanneling and bProtectChannelSkill and dwSkillID == 300) then
		if tSkillCastFrame and (not bWasChanneling or dwSkillID == 300) then
			tSkillCastFrame[dwSkillID] = nCur
		end
		if dwSkillID ~= 300 and nCur + 6 > nNgungThanCooldownUntilFrame then
			nNgungThanCooldownUntilFrame = nCur + 6
		end
		PrepareGroundSkillOnTarget(dwSkillID)
		OnAddOnUseSkill(dwSkillID, dwLevel)
		if dwSkillID == 300 then
			dwCurrentChannelSkillID = 300
		end
		if tGroundTargetSkill[dwSkillID] or dwSkillID == 2212 or (tCombatGroundSkills and tCombatGroundSkills[dwSkillID]) then
			DoSmartSelectPoint(dwSkillID)
		end
		local now = (GetTime and GetTime()) or 0
		local skill = (GetSkill and GetSkill(dwSkillID, dwLevel)) or nil
		local bIsChan = (skill and skill.bIsChannelSkill) or tChannelSkill[dwSkillID]
		local bIsGround = (tGroundTargetSkill and tGroundTargetSkill[dwSkillID]) or dwSkillID == 2212 or (tCombatGroundSkills and tCombatGroundSkills[dwSkillID])
		if now > 0 and not tOffGCDSkill[dwSkillID] and not bIsChanneling and not bWasChanneling then
			local nLock = bIsGround and 650 or (bIsChan and 500 or 260)
			if now + nLock > nGlobalCastLockUntil then
				nGlobalCastLockUntil = now + nLock
			end
		end
		local szName = (Table_GetSkillName and Table_GetSkillName(dwSkillID, dwLevel)) or tostring(dwSkillID)
		if XMCore_Sys then
			XMCore_Sys("[xMacro] -> " .. tostring(szName))
		end
		if bIsChan and bProtectChannelSkill and dwSkillID ~= 300 then
			return false
		end
		return true
	end
	return true
end


