				if nNextSunLevel > 3 then
					nNextSunLevel, dwLastSunTime = 1, 0
				end
			end
		elseif me.dwForceID == 7 then
			if arg1 == 3360 then
				bAttackState = true
			elseif arg1 == 3382 or arg1 == 3368 or arg1 == 3369 then
				bAttackState = false
			end
		elseif me.dwForceID == 6 then
			if arg1 == 2223 or arg1 == 2226 then
				if tSkillCastFrame then tSkillCastFrame[2477] = 0 end
			end
		end
	end
